using System;
using System.Collections.Generic;
using System.Linq;

public record Harvest(string Farmer, string Crop, int Kg);

class Program
{
    static void Main()
    {
        var h = new List<Harvest>
        {
            new("Amina", "maize", 40), new("Juma", "beans", 25),
            new("Amina", "beans", 30), new("Wanjiru", "maize", 55),
        };

        Console.WriteLine(h.Sum(x => x.Kg));                                    // 150
        Console.WriteLine(h.Any(x => x.Kg > 50) + " " + h.All(x => x.Kg > 20));  // True True

        var perCrop = h.GroupBy(x => x.Crop)
                       .Select(g => new { Crop = g.Key, Kg = g.Sum(x => x.Kg) })
                       .OrderByDescending(t => t.Kg).ThenBy(t => t.Crop);
        foreach (var t in perCrop) Console.WriteLine($"{t.Crop}: {t.Kg} kg");

        var first = h.FirstOrDefault(x => x.Crop == "rice");
        Console.WriteLine(first == null ? "no rice" : first.Farmer);
    }
}

