using System;
using System.Collections.Generic;
using System.Linq;

public class Harvest
{
    public string Farmer { get; }
    public string Crop { get; }
    public int Kg { get; }

    public Harvest(string farmer, string crop, int kg)
    {
        Farmer = farmer;
        Crop = crop;
        Kg = kg;
    }
}

public static class Report
{
    public static int TotalKg(List<Harvest> h, string crop) =>
        h.Where(x => x.Crop.Equals(crop, StringComparison.OrdinalIgnoreCase)).Sum(x => x.Kg);

    public static List<string> Farmers(List<Harvest> h) =>
        h.Select(x => x.Farmer).Distinct().OrderBy(n => n).ToList();

    public static string BestCrop(List<Harvest> h)
    {
        if (!h.Any()) return "none";
        return h.GroupBy(x => x.Crop)
                .OrderByDescending(g => g.Sum(x => x.Kg))
                .ThenBy(g => g.Key)
                .First().Key;
    }

    public static List<string> Totals(List<Harvest> h) =>
        h.GroupBy(x => x.Farmer)
         .Select(g => new { Name = g.Key, Kg = g.Sum(x => x.Kg) })
         .OrderByDescending(t => t.Kg)
         .ThenBy(t => t.Name)
         .Select(t => $"{t.Name}: {t.Kg}")
         .ToList();
}

