using System;
using System.Collections.Generic;
using System.Linq;

public class Score
{
    public string Player { get; }
    public int Points { get; }
    public int Level { get; }

    public Score(string player, int points, int level)
    {
        Player = player;
        Points = points;
        Level = level;
    }
}

public static class Board
{
    public static List<string> Top(List<Score> s, int n) =>
        s.OrderByDescending(x => x.Points)
         .ThenBy(x => x.Player)
         .Take(n)
         .Select(x => $"{x.Player}:{x.Points}")
         .ToList();

    public static double AverageOn(List<Score> s, int level)
    {
        var onLevel = s.Where(x => x.Level == level).ToList();
        if (onLevel.Count == 0) return 0;                // Average() would throw on nothing
        return Math.Round(onLevel.Average(x => x.Points), 1);
    }

    public static string Status(List<Score> s, int target)
    {
        if (!s.Any(x => x.Points >= target)) return "none";   // also covers an empty list
        return s.All(x => x.Points >= target) ? "all" : "some";
    }

    // FirstOrDefault gives null when nothing matches; ?. and ?? turn that into "nobody".
    public static string FirstOver(List<Score> s, int points) =>
        s.FirstOrDefault(x => x.Points > points)?.Player ?? "nobody";
}

