using System;
using System.Collections.Generic;
using System.Linq;

public class Visit
{
    public string Clinic { get; }
    public string Patient { get; }
    public int Day { get; }

    public Visit(string clinic, string patient, int day)
    {
        Clinic = clinic;
        Patient = patient;
        Day = day;
    }
}

public static class ClinicStats
{
    public static List<string> PerClinic(List<Visit> v) =>
        v.GroupBy(x => x.Clinic)
         .OrderByDescending(g => g.Count())
         .ThenBy(g => g.Key)
         .Select(g => $"{g.Key}: {g.Count()}")
         .ToList();

    public static int BusiestDay(List<Visit> v)
    {
        if (!v.Any()) return -1;
        return v.GroupBy(x => x.Day)
                .OrderByDescending(g => g.Count())
                .ThenBy(g => g.Key)
                .First().Key;
    }

    public static List<string> Regulars(List<Visit> v, int minVisits) =>
        v.GroupBy(x => x.Patient)
         .Where(g => g.Count() >= minVisits)
         .Select(g => g.Key)
         .OrderBy(name => name)
         .ToList();
}
